<script setup>
import { onMounted, ref } from 'vue';
import KfeFormShell from './KfeFormShell.vue';
const props=defineProps({application:{type:Object,required:true}});
const emit=defineEmits(['save-request','back']);
const showForm=ref(false),detail=ref(''),records=ref([]),loading=ref(false),error=ref('');
const categories=['Service','Tyres','Brakes','Battery','Repair','Other'];
const initial={maintenanceId:'',date:new Date().toISOString().slice(0,10),vehicle:'Current vehicle',odometer:'',category:'',description:'',amount:'',reference:'',workSessionId:''};
async function load(){loading.value=true;error.value='';try{const model=await props.application.getAdminState();records.value=model?.history?.maintenance||[]}catch(e){error.value=String(e?.message||e);records.value=[]}finally{loading.value=false}}
function save(value){emit('save-request',{module:'Maintenance',value});}
function openDetail(value){detail.value=value;if(value==='history')void load();}
function closeDetail(){detail.value='';}
onMounted(load);
const money=value=>`₹${(Number(value||0)/100).toFixed(2)}`;
</script>
<template><section class="kfe-module-view" aria-labelledby="maintenance-title"><button class="kfe-secondary-action" type="button" @click="detail?closeDetail():showForm?showForm=false:emit('back')">‹ {{detail?'Maintenance':showForm?'Maintenance':'More'}}</button><template v-if="detail"><p class="kfe-eyebrow">Vehicle Operations</p><h1 id="maintenance-title">{{detail==='history'?'Maintenance history':'Maintenance categories'}}</h1><p v-if="loading" class="kfe-boundary-note" role="status">Loading authoritative maintenance records…</p><p v-if="error" class="kfe-error-note" role="alert">{{error}}</p><template v-if="detail==='history'"><article v-for="row in records.sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')))" :key="row.id" class="kfe-detail-card"><strong>{{row.category||'Maintenance'}} · {{money(row.amount_paise)}}</strong><p>{{row.date}} · {{row.odometer}} km · {{row.description||'No description'}}</p><small>{{row.vehicle||'Current vehicle'}}{{row.reference?' · '+row.reference:''}}</small></article><p v-if="!loading&&!records.length" class="kfe-boundary-note">No maintenance records yet.</p></template><article v-else class="kfe-detail-card"><strong>Maintenance catalogue</strong><div class="kfe-module-list"><div v-for="category in categories" :key="category" class="kfe-detail-card"><strong>{{category}}</strong></div></div></article></template><template v-else-if="!showForm"><p class="kfe-eyebrow">Vehicle Operations</p><h1 id="maintenance-title">Maintenance</h1><p class="kfe-destination-subtitle">Vehicle maintenance records and usage context.</p><article class="kfe-action-card"><div><span class="kfe-card-label">Maintenance</span><strong>Record vehicle work</strong><p>Usage-based allocation is handled by the business layer.</p></div><button class="kfe-primary-action" type="button" @click="showForm=true">Add maintenance</button></article><section class="kfe-module-section"><h2>History</h2><button class="kfe-list-action" type="button" @click="openDetail('history')"><span>Maintenance history</span><span aria-hidden="true">›</span></button></section><section class="kfe-module-section"><h2>Catalogue</h2><button class="kfe-list-action" type="button" @click="openDetail('categories')"><span>Maintenance categories</span><span aria-hidden="true">›</span></button></section></template><KfeFormShell v-else draft-key="maintenance-entry" title="Add maintenance" subtitle="Required record information first; supporting links remain optional." :initial-value="initial" @save="save"><template #default="{value}"><div class="kfe-form-field"><label class="kfe-form-label" for="maintenance-id">Maintenance ID <span class="kfe-optional">Optional</span></label><input id="maintenance-id" v-model="value.maintenanceId" class="kfe-form-input" type="text" /></div><div class="kfe-form-grid"><div class="kfe-form-field"><label class="kfe-form-label" for="maintenance-date">Date</label><input id="maintenance-date" v-model="value.date" class="kfe-form-input" type="date" required /></div><div class="kfe-form-field"><label class="kfe-form-label" for="maintenance-odometer">Odometer</label><input id="maintenance-odometer" v-model="value.odometer" class="kfe-form-input" type="number" min="0" step="1" required /></div></div><div class="kfe-form-field"><label class="kfe-form-label" for="maintenance-category">Category</label><select id="maintenance-category" v-model="value.category" class="kfe-form-input" required><option value="" disabled>Select category</option><option v-for="category in categories" :key="category" :value="category">{{category}}</option></select></div><div class="kfe-form-field"><label class="kfe-form-label" for="maintenance-description">Description</label><input id="maintenance-description" v-model="value.description" class="kfe-form-input" type="text" required /></div><div class="kfe-form-field"><label class="kfe-form-label" for="maintenance-amount">Amount</label><input id="maintenance-amount" v-model="value.amount" class="kfe-form-input" type="number" min="0" step="0.01" required /></div><details class="kfe-optional-details"><summary>Optional supporting information</summary><div class="kfe-form-field"><label class="kfe-form-label" for="maintenance-reference">Receipt / reference</label><input id="maintenance-reference" v-model="value.reference" class="kfe-form-input" type="text" /></div><div class="kfe-form-field"><label class="kfe-form-label" for="maintenance-session">Work Session ID</label><input id="maintenance-session" v-model="value.workSessionId" class="kfe-form-input" type="text" /></div></details></template></KfeFormShell></section></template>